html:
{%- set invoice = doc -%}
{%- set agency = frappe.get_doc("AgencyProfile", invoice.agency) if invoice.agency else None -%}
{%- set project_title = frappe.db.get_value("Project", invoice.project, "title") if invoice.project else None -%}
{%- set generated_at = frappe.utils.now_datetime().strftime("%d/%m/%Y à %H:%M") -%}
{%- set issue_date_display = frappe.utils.formatdate(invoice.issue_date) if invoice.issue_date else generated_at -%}
{%- set due_date_display = frappe.utils.formatdate(invoice.due_date) if invoice.due_date else None -%}
{%- set payment_date_display = frappe.utils.formatdate(invoice.payment_date) if invoice.payment_date else None -%}
{%- set STATUS_LABELS = {"Pending": "En attente", "Paid": "Payée", "Overdue": "En retard", "Cancelled": "Annulée"} -%}
{%- set status_label = STATUS_LABELS.get(invoice.status, invoice.status) -%}
{%- set commission_ht = invoice.commission_amount or 0 -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value or 0).replace(",", " ") }} €{%- endmacro -%}
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>Facture — {{ invoice.invoice_number or invoice.name }}</title>
<style>
	body { font-family: Arial, Helvetica, sans-serif; color: #1a1a1a; font-size: 12px; margin: 0; padding: 26px; background: #ffffff; }
	.sheet { max-width: 680px; margin: 0 auto; }

	.top-row { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 22px; page-break-inside: avoid; }
	.brand-name { font-size: 15px; font-weight: bold; }
	.brand-sub { font-size: 10.5px; color: #666666; margin-top: 2px; margin-bottom: 12px; }
	.dates div { font-size: 11px; color: #444444; margin-bottom: 2px; }
	.doc-title { font-size: 30px; font-weight: bold; letter-spacing: 0.02em; text-align: right; text-transform: uppercase; }
	.doc-ref { font-size: 12px; color: #555555; margin-top: 2px; text-align: right; font-weight: bold; }

	.parties-row { display: flex; justify-content: space-between; gap: 30px; margin: 22px 0 16px 0; page-break-inside: avoid; }
	.party { flex: 1; font-size: 11.5px; line-height: 1.6; }
	.party-name { font-weight: bold; font-size: 13px; margin-bottom: 4px; }
	.party-kicker { font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: #777777; margin-bottom: 6px; }

	.ref-box { border: 1px solid #e4e1da; border-radius: 6px; padding: 10px 14px; font-size: 11px; color: #555555;
		margin-bottom: 18px; page-break-inside: avoid; }
	.ref-box div { margin-bottom: 3px; }
	.ref-box div:last-child { margin-bottom: 0; }

	.section-heading { font-size: 14px; font-weight: bold; border-bottom: 1.5px solid #1a1a1a; padding-bottom: 6px; margin-bottom: 10px; page-break-after: avoid; }

	table.items { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
	table.items th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: #777777; padding: 0 0 6px 0; border-bottom: 1px solid #d8d2c8; }
	table.items th.num { text-align: right; }
	table.items td { padding: 8px 0; font-size: 12px; border-bottom: 1px solid #ece7df; vertical-align: top; }
	table.items td.num { text-align: right; white-space: nowrap; }
	table.items .item-detail { display: block; font-size: 10.5px; color: #777777; margin-top: 2px; }
	table.items tr { page-break-inside: avoid; }

	table.totals { width: 100%; margin-top: 4px; page-break-inside: avoid; }
	table.totals td { padding: 4px 0; font-size: 12px; }
	table.totals td.label { text-align: right; padding-right: 18px; color: #555555; }
	table.totals td.value { text-align: right; width: 110px; }
	table.totals tr.total td { font-weight: bold; font-size: 14px; border-top: 1.5px solid #1a1a1a; padding-top: 8px; }
	table.totals tr.due td { font-weight: bold; }

	.bottom-row { display: flex; justify-content: space-between; gap: 30px; margin-top: 32px; page-break-inside: avoid; }
	.bottom-col { flex: 1; font-size: 10.5px; color: #444444; line-height: 1.6; }
	.bottom-heading { font-weight: bold; color: #1a1a1a; margin-bottom: 6px; }
</style>
</head>
<body>
<div class="sheet">

	<div class="top-row">
		<div>
			<div class="brand-name">Sortlist Pro</div>
			<div class="brand-sub">Facturation de commission</div>
			<div class="dates">
				<div>Date : {{ issue_date_display }}</div>
				{%- if due_date_display -%}<div>Échéance : {{ due_date_display }}</div>{%- endif -%}
			</div>
		</div>
		<div>
			<div class="doc-title">Facture</div>
			<div class="doc-ref">N° {{ invoice.invoice_number or invoice.name }}</div>
		</div>
	</div>

	<div class="parties-row">
		<div class="party">
			<div class="party-kicker">Émetteur</div>
			<div class="party-name">Sortlist Pro</div>
			<div>Commission de mise en relation agences ↔ clients</div>
		</div>
		<div class="party" style="text-align: right;">
			<div class="party-kicker">Destinataire</div>
			<div class="party-name">{{ (agency.agency_name if agency else None) or "Agence" }}</div>
			{%- if agency and (agency.billing_email or agency.email) -%}<div>{{ agency.billing_email or agency.email }}</div>{%- endif -%}
			{%- if agency and (agency.billing_address or agency.address) -%}<div>{{ agency.billing_address or agency.address }}</div>{%- endif -%}
			{%- if agency and agency.vat_number -%}<div>TVA : {{ agency.vat_number }}</div>{%- endif -%}
		</div>
	</div>

	<div class="ref-box">
		{%- if project_title -%}<div>Projet concerné : {{ project_title }}</div>{%- endif -%}
		{%- if invoice.proposal -%}<div>Offre : {{ invoice.proposal }}</div>{%- endif -%}
		<div>Montant de la prestation (base de calcul) : {{ money(invoice.amount) }}</div>
	</div>

	<div class="section-heading">Description</div>
	<table class="items">
		<thead>
			<tr>
				<th>Désignation</th>
				<th class="num">Prix unitaire</th>
				<th class="num">Quantité</th>
				<th class="num">Total</th>
			</tr>
		</thead>
		<tbody>
			<tr>
				<td>
					Commission de mise en relation{% if project_title %} — {{ project_title }}{% endif %}
					<span class="item-detail">{{ money(invoice.amount) }} × {{ invoice.commission_rate or 0 }}% de commission</span>
				</td>
				<td class="num">{{ money(commission_ht) }}</td>
				<td class="num">1</td>
				<td class="num">{{ money(commission_ht) }}</td>
			</tr>
		</tbody>
	</table>

	<table class="totals">
		<tr><td class="label">Total HT :</td><td class="value">{{ money(commission_ht) }}</td></tr>
		<tr><td class="label">TVA :</td><td class="value">{{ money(invoice.tax) if invoice.tax else "–" }}</td></tr>
		<tr class="total"><td class="label">Total TTC :</td><td class="value">{{ money(invoice.total) }}</td></tr>
		{%- if invoice.credit_applied -%}
		<tr><td class="label">Crédit appliqué :</td><td class="value">- {{ money(invoice.credit_applied) }}</td></tr>
		{%- endif -%}
		<tr class="due"><td class="label">Net à payer :</td><td class="value">{{ money(invoice.amount_due) }}</td></tr>
	</table>

	<div class="bottom-row">
		<div class="bottom-col">
			<div class="bottom-heading">Règlement</div>
			<div>Statut : {{ status_label }}</div>
			{%- if payment_date_display -%}<div>Payée le {{ payment_date_display }}</div>{%- endif -%}
			<div>Paiement par carte via la plateforme (Facturation → Moyens de paiement).</div>
		</div>
		<div class="bottom-col">
			<div class="bottom-heading">Conditions</div>
			{%- if invoice.commission_rate -%}<div>Taux de commission appliqué : {{ invoice.commission_rate }}%.</div>{%- endif -%}
			<div>En cas de retard de paiement prolongé, les offres de l'agence peuvent être suspendues jusqu'à régularisation.</div>
		</div>
	</div>

</div>
</body>
</html>
